// FindOneCacheByID 根据ID查询一条数据，并设置缓存
func (n *NpRepo) FindOneCacheByID(ctx context.Context, ID string) (*devices_learn_model.Np, error) {
	resp := new(devices_learn_model.Np)
	cacheKey := n.cache.Key(CacheNpByIDPrefix, ID)
	cacheValue, err := n.cache.Fetch2(ctx, cacheKey, func() (string, error) {
		dao := devices_learn_dao.Use(n.db).Np
		result, err := dao.WithContext(ctx).Where(dao.ID.Eq(ID)).First()
		if err != nil && !errors.Is(err, gorm.ErrRecordNotFound) {
			return "", err
		}
		marshal, err := n.encoding.Marshal(result)
		if err != nil {
			return "", err
		}
		return string(marshal), nil
	}, n.cache.TTL())
	if err != nil {
		return nil, err
	}
	if cacheValue != "" {
		err = n.encoding.Unmarshal([]byte(cacheValue), resp)
		if err != nil {
			return nil, err
		}
	}
	return resp, nil
}

