// DeleteUniqueIndexCache 删除索引存在的缓存
func (n *NpRepo) DeleteIndexCache(ctx context.Context, data ...*devices_learn_model.Np) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, n.cache.Key(CacheNpByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[n.cache.Key(CacheNpByIDPrefix, item.ID)] = struct{}{}
			KeyMap[n.cache.Key(CacheNpBySNIDPrefix, item.SNID)] = struct{}{}
			KeyMap[n.cache.Key(CacheNpByPopupCaseGroupPrefix, item.PopupCaseGroup)] = struct{}{}
			KeyMap[n.cache.Key(CacheNpByStagePrefix, item.Stage)] = struct{}{}
			KeyMap[n.cache.Key(CacheNpByUserIDPrefix, item.UserID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := n.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
